        profile = DB.fetch_one("SELECT id FROM user_profiles WHERE user_id = %s", (user['id'],))
        if profile:
            sets = ', '.join([f"{k} = %s" for k in data.keys()])
            DB.execute(f"UPDATE user_profiles SET {sets} WHERE user_id = %s", list(data.values()) + [user['id']])
        else:
