  // Donation Management
  async recordDonation(data: Partial<Donation>): Promise<Donation> {
    const response = await fetch(`${API_BASE_URL}/blood-donor/donations`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify(data)
    });
    return response.json();
